  if (total > 0) {
    let largest = 0;
    cutShares.forEach((share, i) => { if (share > cutShares[largest]) largest = i; });
    raw[largest] += potCents - raw.reduce((sum, c) => sum + c, 0);
  }
  pool.members.forEach((m, i) => cutsByKey.set(memberKey(m), money(raw[i])));
  return cutsByKey;
}

